Compose_OTP_Veriify_Structure_Update.inputs:
"Case_Verify": {
          "case": "verify",
          "actions": {
            "Compose_OTP_Identifier_Verify": {
              "type": "Compose",
              "inputs": @{trim(string(coalesce(triggerBody()?['identifier'], triggerBody()?['userEmail'], triggerBody()?['id'], triggerBody()?['device']?['id'], '')))}
            },
            "Compose_OTP_Code_Verify": {
              "type": "Compose",
              "inputs": @{trim(string(coalesce(triggerBody()?['otp_code'], '')))},
              "runAfter": {
                "Compose_OTP_Identifier_Verify": [
                  "Succeeded"
                ]
              }
            },
            "Condition_Verify_Inputs_Required": {
              "type": "If",
              "expression": {
                "or": [
                  {
                    "equals": [
                      @{empty(trim(string(coalesce(outputs('Compose_OTP_Identifier_Verify'), ''))))},
                      true
                    ]
                  },
                  {
                    "equals": [
                      @{empty(trim(string(coalesce(outputs('Compose_OTP_Code_Verify'), ''))))},
                      true
                    ]
                  }
                ]
              },
              "actions": {
                "Set_variable_varStatusCode_Verify_Missing_Input": {
                  "type": "SetVariable",
                  "inputs": {
                    "name": "varStatusCode",
                    "value": 400
                  }
                },
                "Append_to_string_variable_varResponse_Verify_Missing_Input": {
                  "type": "SetVariable",
                  "inputs": {
                    "name": "varResponse",
                    "value": {
                      "valid": false,
                      "code": "OTP_INPUT_REQUIRED",
                      "message": "identifier/userEmail and otp_code are required to verify an OTP."
                    }
                  },
                  "runAfter": {
                    "Set_variable_varStatusCode_Verify_Missing_Input": [
                      "Succeeded"
                    ]
                  }
                }
              },
              "else": {
                "actions": {
                  "Get_items": {
                    "type": "OpenApiConnection",
                    "inputs": {
                      "parameters": {
                        "dataset": "https://nitdanigeria.sharepoint.com/sites/NITDADGO-EAAACTIVITYTRACKING",
                        "table": "9421d473-8906-43b7-a41f-a213046683c1",
                        "$filter": @{concat('Title eq ''', replace(outputs('Compose_OTP_Identifier_Verify'), '''', ''''''), ''' and Is_Verified eq false')},
                        "$orderby": "Created desc",
                        "$top": 1
                      },
                      "host": {
                        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline",
                        "connection": "shared_sharepointonline",
                        "operationId": "GetItems"
                      }
                    }
                  },
                  "Compose_Count_Items_Check": {
                    "type": "Compose",
                    "inputs": @{length(coalesce(outputs('Get_items_OTP_Verify')?['body']?['value'], json('[]')))},
                    "runAfter": {
                      "Get_items": [
                        "Succeeded"
                      ]
                    }
                  },
                  "Condition": {
                    "type": "If",
                    "expression": {
                      "less": [
                        @{int(coalesce(outputs('Compose_Count_Items_Check'), 0))},
                        1
                      ]
                    },
                    "actions": {
                      "Set_variable_varStatusCode_No_Pending_OTP_Found": {
                        "type": "SetVariable",
                        "inputs": {
                          "name": "varStatusCode",
                          "value": 404
                        }
                      },
                      "Append_to_string_variable_varResponse_No_Pending_OTP_Found": {
                        "type": "SetVariable",
                        "inputs": {
                          "name": "varResponse",
                          "value": {
                            "valid": false,
                            "code": "OTP_NOT_FOUND",
                            "message": "No pending OTP was found for this identifier."
                          }
                        },
                        "runAfter": {
                          "Set_variable_varStatusCode_No_Pending_OTP_Found": [
                            "Succeeded"
                          ]
                        }
                      }
                    },
                    "else": {
                      "actions": {
                        "Condition_Code_Matches": {
                          "type": "If",
                          "expression": {
                            "equals": [
                              @{trim(string(coalesce(first(outputs('Get_items_OTP_Verify')?['body']?['value'])?['OTP_Code'], '')))},
                              @{outputs('Compose_OTP_Code_Verify')}
                            ]
                          },
                          "actions": {
                            "Condition_Not_Expired": {
                              "type": "If",
                              "expression": {
                                "greater": [
                                  @{ticks(coalesce(first(outputs('Get_items_OTP_Verify')?['body']?['value'])?['Expires_At'], '1900-01-01T00:00:00Z'))},
                                  @{ticks(utcNow())}
                                ]
                              },
                              "actions": {
                                "Update_item": {
                                  "type": "OpenApiConnection",
                                  "inputs": {
                                    "parameters": {
                                      "dataset": "https://nitdanigeria.sharepoint.com/sites/NITDADGO-EAAACTIVITYTRACKING",
                                      "table": "9421d473-8906-43b7-a41f-a213046683c1",
                                      "id": @{coalesce(first(outputs('Get_items_OTP_Verify')?['body']?['value'])?['ID'], first(outputs('Get_items_OTP_Verify')?['body']?['value'])?['Id'])},
                                      "item/Title": @{coalesce(first(outputs('Get_items_OTP_Verify')?['body']?['value'])?['Title'], outputs('Compose_OTP_Identifier_Verify'))},
                                      "item/Is_Verified": true
                                    },
                                    "host": {
                                      "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline",
                                      "connection": "shared_sharepointonline",
                                      "operationId": "PatchItem"
                                    }
                                  }
                                },
                                "Set_variable_Verification_Successful_Status": {
                                  "type": "SetVariable",
                                  "inputs": {
                                    "name": "varStatusCode",
                                    "value": 200
                                  },
                                  "runAfter": {
                                    "Update_item": [
                                      "Succeeded"
                                    ]
                                  }
                                },
                                "Append_to_string_variable_Verification_Successful": {
                                  "type": "SetVariable",
                                  "inputs": {
                                    "name": "varResponse",
                                    "value": {
                                      "valid": true,
                                      "message": "Verification successful",
                                      "verificationToken": @{variables('varRequestId')},
                                      "otpId": @{string(coalesce(first(outputs('Get_items_OTP_Verify')?['body']?['value'])?['ID'], first(outputs('Get_items_OTP_Verify')?['body']?['value'])?['Id'], ''))}
                                    }
                                  },
                                  "runAfter": {
                                    "Set_variable_Verification_Successful_Status": [
                                      "Succeeded"
                                    ]
                                  }
                                }
                              },
                              "else": {
                                "actions": {
                                  "Set_variable_OTP_Expired_Status": {
                                    "type": "SetVariable",
                                    "inputs": {
                                      "name": "varStatusCode",
                                      "value": 410
                                    }
                                  },
                                  "Append_to_string_variable_OTP_Expired": {
                                    "type": "SetVariable",
                                    "inputs": {
                                      "name": "varResponse",
                                      "value": {
                                        "valid": false,
                                        "code": "OTP_EXPIRED",
                                        "message": "OTP expired."
                                      }
                                    },
                                    "runAfter": {
                                      "Set_variable_OTP_Expired_Status": [
                                        "Succeeded"
                                      ]
                                    }
                                  }
                                }
                              }
                            }
                          },
                          "else": {
                            "actions": {
                              "Set_variable_OTP_Invalid_Status": {
                                "type": "SetVariable",
                                "inputs": {
                                  "name": "varStatusCode",
                                  "value": 401
                                }
                              },
                              "Append_to_string_variable_OTP_Invalid": {
                                "type": "SetVariable",
                                "inputs": {
                                  "name": "varResponse",
                                  "value": {
                                    "valid": false,
                                    "code": "OTP_INVALID",
                                    "message": "Invalid OTP code."
                                  }
                                },
                                "runAfter": {
                                  "Set_variable_OTP_Invalid_Status": [
                                    "Succeeded"
                                  ]
                                }
                              }
                            }
                          }
                        }
                      }
                    },
                    "runAfter": {
                      "Compose_Count_Items_Check": [
                        "Succeeded"
                      ]
                    }
                  }
                }
              },
              "runAfter": {
                "Compose_OTP_Code_Verify": [
                  "Succeeded"
                ]
              }
            }
          }
        }
      }
    }

inputs.value:
@if(
  equals(coalesce(variables('varStartTicks'), 0), 0),
  0,
  max(
    div(
      sub(
        ticks(
          coalesce(
            variables('varCompletedAtUtc'),
            utcNow()
          )
        ),
        variables('varStartTicks')
      ),
      10000
    ),
    0
  )
)
